  {
    "name": "gmail_find_email",
    "description": "Search for emails using Gmail search operators.\n\nArgs:\n    query: Gmail search query. Supports operators: from:, to:, subject:,\n        label:, is:unread, is:read, is:starred, has:attachment, OR, and\n        plain text (e.g., \"from:user@example.com is:unread\").\n    id: Message ID for direct lookup (returns single message).\n    label: Filter by label (e.g., \"INBOX\", \"SENT\").\n    max_results: Maximum number of results to return.\n    include_spam_trash: Include spam and trash in results.\n    format: Email format to return (\"full\", \"metadata\", \"minimal\", \"raw\").\n\nReturns:\n    JSON string with matching messages.",
    "parameters": {
      "properties": {
        "query": {
          "default": "",
          "description": "Gmail search query. Supports operators: from:, to:, subject:,\nlabel:, is:unread, is:read, is:starred, has:attachment, OR, and\nplain text (e.g., \"from:user@example.com is:unread\").",
          "title": "Query",
          "type": "string"
        },
        "id": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Message ID for direct lookup (returns single message).",
          "title": "Id"
        },
        "label": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter by label (e.g., \"INBOX\", \"SENT\").",
          "title": "Label"
        },
        "max_results": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": 10,
          "description": "Maximum number of results to return.",
          "title": "Max Results"
        },
        "include_spam_trash": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "default": false,
          "description": "Include spam and trash in results.",
          "title": "Include Spam Trash"
        },
        "format": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "full",
          "description": "Email format to return (\"full\", \"metadata\", \"minimal\", \"raw\").",
          "title": "Format"
        }
      },
      "title": "gmail_find_email_args",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "query",
        "id",
        "label",
        "max_results",
        "include_spam_trash",
        "format"
      ]
    }
  },
